class Rule {
    static int choose(int bonus) {
        int value = 2;
        // 반환을 finally 뒤로 옮겨 finally에서 바꾼 값을 반환하세요.
        try { return value; }
        finally {
            value += bonus;
            System.out.print("F");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int bonus = 7;
        System.out.println(Rule.choose(bonus));
