tasks.solution:
class Rule {
    static int choose(int bonus) {
        int value = 2;
        // 반환을 finally 뒤로 옮겨 finally에서 바꾼 값을 반환하세요.
        // try 안의 return은 finally 전에 반환값을 정해 둬요. 바뀐 값을 돌려주려면 finally 뒤에서 반환해요.
        try { System.out.print(""); }
        finally {
            value += bonus;
            System.out.print("F");
        }
        return value;
    }
}

public class Main {
    public static void main(String[] args) {
        int bonus = 7;
        System.out.println(Rule.choose(bonus));
    }
}

